-- Approved product copy 1.1. Retains earlier acceptances and requests fresh acceptance.
update public.lx_legal_documents set is_current=false where document_type in ('terms','privacy') and is_current;
insert into public.lx_legal_documents(document_type,version,title_ar,body_ar,published_at,requires_reacceptance,is_current) values
('terms','1.1','شروط استخدام LXHAZZAA',
$$تقدم LXHAZZAA بوابة بحثية تشمل أطلس الرفات القديمة وموسوعة الوثائق والمخطوطات والنقوش. يلتزم المستخدم بعدم انتحال الصفة أو نشر معلومات مخالفة للأنظمة أو حقوق الآخرين. تخضع المساهمات للمراجعة قبل النشر، ولا يعني قبولها القطع بصحة جميع بياناتها.

تختلف ملكية الأصل عن حقوق تصويره وإتاحته وعن حقوق التحقيق والتفريغ والترجمة. يذكر المساهم المالك والجهة الحافظة ورقم الحفظ والمصدر وشروط الإتاحة، وينسب العمل العلمي لأصحابه بحسب دورهم. فهرسة مادة من أرشيف أو مكتبة لا تمنح حق إعادة نشر صورتها. عندما لا يسمح الترخيص بذلك، يجوز تقديم بياناتها الوصفية المباحة ورابط مصدرها فقط. يقر رافع المادة أن لديه أساسًا مشروعًا لما يتيحه ويقدم دليل الحق أو التصريح عند الطلب، ويتحمل مسؤولية صحة إقراراته دون إخلال بالتزامات المنصة النظامية. يمنح LXHAZZAA ترخيصًا غير حصري لعرض مساهمته وفهرستها ضمن حدود الحقوق التي يملكها؛ ولا تنتقل ملكية المادة الأصلية إلى المنصة.

تُعرض الصور والصفحات المتاحة بالفعل فقط. يعرض التفريغ بلغته الأصلية قبل ترجمته، مع بيان حالة القراءة والترجمة والمراجعة. لا تقدم الأجزاء التالفة أو التخمينات بوصفها نصوصًا مؤكدة. لا يجوز استعمال ختم أو علامة مائية توهم بملكية الأصل أو تطمس علامة مالكه؛ وتضاف العلامات إلى نسخ العرض المسموح بها دون تغيير الأصل المحفوظ. يتحكم ترخيص المصدر فيما يجوز عرضه أو تنزيله أو إدخاله في تقرير PDF، وتظهر نسب الباحث والمصدر على بطاقات العرض والتصدير.

بيانات أطلس الرفات أثرية وجينية قابلة للتحديث. يبيّن السجل مصدر العينة ودقة موقعها وطريقة تأريخها وحالة الثقة في التحور. لا يثبت التحور أو العينة القديمة وحدهما نسبًا شخصيًا أو هوية إثنية معاصرة. تُراعى تراخيص قواعد البيانات؛ ولا يجوز إدخال بيانات جينية لأشخاص أحياء دون أساس مشروع وضوابط خصوصية.

يمكن لصاحب الحق أو الباحث أو الجهة الحافظة الاعتراض على النشر أو النسبة أو الدقة عبر بريد التواصل في الموقع. قد تقيد المنصة العرض أو التنزيل أثناء المراجعة، ثم تصحح أو تزيل المادة بحسب نتيجة التحقق. يمكن تحديث هذه الشروط، وتُطلب موافقة جديدة عندما تتطلب التغييرات ذلك. لا تسقط هذه الشروط الحقوق النظامية للمستخدم.$$,
now(),true,true),
('privacy','1.1','سياسة الخصوصية في LXHAZZAA',
$$تُعالج LXHAZZAA بيانات الحساب اللازمة لتسجيل الدخول، والاسم الظاهر والرتبة، وسجل البحث المحفوظ للحساب، وإصدارات الشروط التي وافق عليها العضو وتواريخ الموافقة. عند تقديم مادة، تُحفظ بيانات المساهمة والملفات التي يختار رفعها وإقرار الحقوق وقرارات المراجعة. يُظهر السجل المنشور بيانات المصدر والنسبة العلمية والإتاحة المصرح بها؛ ولا يُظهر بريد العضو الشخصي ضمن اسمه الظاهر.

يُستخدم هذا القدر من البيانات لتشغيل الحساب والبحث ومراجعة المساهمات وحماية الحقوق والرد على التصحيحات والاعتراضات. تدار المصادقة والتخزين بواسطة مزوّدي الخدمة التقنيين المرتبطين بالمنصة. تبقى ملفات الأصول المرفوعة في تخزين خاص، ويصل إليها المساهم والمراجعون المخوّلون؛ وتُنشر البيانات التي اعتمدت للمشاهدة العامة فقط. يمكن للعضو مسح سجل البحث من صفحة حسابه، وتقديم طلب متعلق ببياناته أو الاعتراض عبر بريد التواصل المنشور.

تُراجع مدد الاحتفاظ ومواقع المعالجة وضوابط النقل وتفاصيل الحذف وفق التشغيل الفعلي والالتزامات النظامية قبل إعلان مدد أو ضمانات محددة. قد تتغير هذه السياسة مع تطور الخدمات، وتُطلب موافقة جديدة عند التغيير الذي يستلزم ذلك. لا يُعد إقرار المساهم إعفاء للمنصة من التزاماتها النظامية.$$,
now(),true,true);
